import{at as e,n as t,ot as n,yt as r}from"./chunks/framework.BVA38fkC.js";var i=JSON.parse(`{"title":"FD Cal UI/UX Improvement and Implementation Plan","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://aaron-fredrick.github.io/FD-Calculator/docs/audits/UI-UX-IMPLEMENTATION-PLAN.html"}],["meta",{"property":"og:title","content":"FD Cal UI/UX Improvement and Implementation Plan | FD Cal Documentation"}],["meta",{"property":"og:description","content":"FD Cal documentation for fixed-deposit planning, investment strategies, bank product data and the shared simulation engine."}],["meta",{"property":"og:url","content":"https://aaron-fredrick.github.io/FD-Calculator/docs/audits/UI-UX-IMPLEMENTATION-PLAN.html"}],["meta",{"name":"twitter:title","content":"FD Cal UI/UX Improvement and Implementation Plan | FD Cal Documentation"}],["meta",{"name":"twitter:description","content":"FD Cal documentation for fixed-deposit planning, investment strategies, bank product data and the shared simulation engine."}]]},"headers":[],"relativePath":"audits/UI-UX-IMPLEMENTATION-PLAN.md","filePath":"audits/UI-UX-IMPLEMENTATION-PLAN.md","lastUpdated":1794147873000}`),a={name:`audits/UI-UX-IMPLEMENTATION-PLAN.md`};function o(t,i,a,o,s,c){return r(),e(`div`,null,[...i[0]||=[n(`<h1 id="fd-cal-ui-ux-improvement-and-implementation-plan" tabindex="-1">FD Cal UI/UX Improvement and Implementation Plan <a class="header-anchor" href="#fd-cal-ui-ux-improvement-and-implementation-plan" aria-label="Permalink to “FD Cal UI/UX Improvement and Implementation Plan”">​</a></h1><p><strong>Status:</strong> Implementation in progress; this plan is the execution source of truth<br><strong>Branch:</strong> <code>docs/ui-ux-audit-charles-skills</code><br><strong>Parent audit:</strong> <a href="./UI-UX-AUDIT-CHARLES-SKILLS.html">UI/UX Audit Findings — Charles Skills Review</a><br><strong>Product:</strong> FD Cal — Sri Lankan fixed-deposit portfolio planning and optimisation</p><h2 id="execution-log" tabindex="-1">Execution log <a class="header-anchor" href="#execution-log" aria-label="Permalink to “Execution log”">​</a></h2><ul><li><strong>2026-11-08 — Phase 0 source revalidation:</strong> the branch head before implementation was <code>251d31a57983b1f106c62bae26f6389ac4a5cbf3</code>, with <code>main</code> as its merge base and no behind commits. The source tree still contains the synchronous <code>simulate(c)</code> call after catalogue loading; UI-009 remains applicable. The canonical token file is unchanged. The current app is native browser ES modules, not a Vite/bundler project; the worker design is therefore native module-worker loading, with no new build dependency.</li><li><strong>Phase 0 evidence still pending:</strong> a local clone attempt failed at DNS resolution, so no pre-change npm test baseline or browser screenshots were captured. The tests workflow was extended to run on pushes to this implementation branch. Automated validation now runs in GitHub Actions; real-browser screenshots, viewport/keyboard checks and small/normal/large report-size measurements remain pending.</li><li><strong>2026-11-08 — Phase 2A implementation:</strong> added a module worker, a pure shared-engine task adapter, a Promise-based single-flight runner, effective-config/catalogue fingerprinting, completed-result reuse, supersession/cancellation, structured-clone rehydration of <code>Booking</code> and <code>SimResult</code> domain behaviour, elapsed-time and submitted-config feedback, plus runner and all-strategy parity tests. Automated tests pass; real-browser responsiveness verification remains open.</li><li><strong>2026-11-08 — Phase 1 implementation:</strong> clarified first-use/privacy copy, aligned the investment-window heading with the journey rail, explained final-valuation consolidation, scheduled-date syntax and outflow payment policies, added strategy-specific descriptions and a distinct search-limits heading, preserved the disabled Goal mode while linking to the feature-request route, and surfaced catalogue age/guardian conditions in report booking details without changing the simulation-context option contract.</li><li><strong>2026-11-08 — Phase 2 implementation:</strong> catalogue-dependent form and import/export controls are gated until both bank/product catalogues load; loading/error/ready states are announced and remain visible on mobile. Unexpected calculation errors are kept generic for users while diagnostics are sent to the developer console without scenario payloads. Existing focus-visible, tooltip keyboard focus, reduced-motion and touch-target rules were retained.</li><li><strong>2026-11-08 — Phase 3 implementation:</strong> the concise in-app summary contract remains unchanged. The standalone report now carries a device-clock UTC timestamp, a SHA-256 fingerprint of the exact product/bank/fee snapshot, privacy and nominal-rate/XIRR explanations, product age-condition details, and collapsible keyboard-accessible data tables adjacent to each canvas chart. Report CSS embeds a generated copy of the canonical brand token block. The current static template payload is approximately 49.2 KB before scenario-specific chart/ledger data; no external runtime assets are required.</li><li><strong>2026-11-08 — Phase 4 implementation:</strong> updated the getting-started journey, project overview, age-eligibility reference, brand-token instructions and documentation home page to describe worker execution, scenario stages, privacy, offline reports, manual eligibility verification and the distinction between summary and full report.</li><li><strong>Verification state:</strong> GitHub Actions run <code>42489584786</code> completed successfully for final implementation tree <code>02682a6abc56f672e0e4d742a096da64f9d6556a</code>: all 212 Node tests passed (0 failures), the generated report-token drift check passed, JavaScript syntax checks passed, the isolated web artifact included all worker modules, the preserved documentation build passed, and workflow YAML validation passed. Browser responsiveness, screenshots, keyboard/reduced-motion/print checks and small/normal/large generated report-size measurements remain mandatory before Phase 5 can close.</li><li><strong>Deferrals:</strong> Section 7 remains unchanged. Analytics/telemetry, broad SEO expansion, decorative redesign/new palette, animation/chart/UI frameworks, financial-engine changes, backend/accounts and automated bank/eligibility verification remain out of scope. No deferred item is being pulled into this implementation.</li></ul><h2 id="_1-purpose" tabindex="-1">1. Purpose <a class="header-anchor" href="#_1-purpose" aria-label="Permalink to “1. Purpose”">​</a></h2><p>This plan turns the audit into an ordered, user-centred improvement programme. The audit records observations and risks; this document decides what should be improved, what should deliberately remain as it is, why the changes fit FD Cal, and how each stage should be implemented and verified.</p><p>The goal is not to redesign FD Cal into a generic SaaS dashboard or to reproduce the appearance of another product. FD Cal is already a working financial-planning application with a shared calculation engine, a browser interface, a CLI, a detailed report generator, bank/product data, and a separately deployed documentation site. The work should improve comprehension, confidence, usability and consistency without destabilising the financial engine or making the interface heavier.</p><p>The Charles Skills are used as design-review frameworks only. We are not invoking Claude, installing those skills into the application, or mechanically following their tool-specific workflows. Their useful principles are translated into project-appropriate engineering and design requirements below.</p><h2 id="_2-product-direction" tabindex="-1">2. Product direction <a class="header-anchor" href="#_2-product-direction" aria-label="Permalink to “2. Product direction”">​</a></h2><h3 id="_2-1-product-definition" tabindex="-1">2.1 Product definition <a class="header-anchor" href="#_2-1-product-definition" aria-label="Permalink to “2.1 Product definition”">​</a></h3><p>FD Cal helps people plan and compare Sri Lankan fixed-deposit portfolios across banks, accounts, product terms, cash movements, tax assumptions and investment strategies. It simulates possible plans; it does not open deposits, transfer money, verify bank eligibility, or execute transactions.</p><h3 id="_2-2-product-character" tabindex="-1">2.2 Product character <a class="header-anchor" href="#_2-2-product-character" aria-label="Permalink to “2.2 Product character”">​</a></h3><ul><li><strong>Character:</strong> precise, calm, transparent.</li><li><strong>World:</strong> a financial planning instrument: account statements, rate schedules, portfolio allocation and an auditable event ledger.</li><li><strong>Primary moment:</strong> the user can move from a small set of understandable scenario inputs to a clear portfolio outcome, then inspect the evidence behind that outcome when needed.</li><li><strong>Signature:</strong> a traceable plan: headline outcome in the app, with the complete account, booking, cash-flow and event detail available in a portable report.</li><li><strong>Concept:</strong> <em>Make the plan easy to understand at a glance, and make every important number inspectable when the user wants the detail.</em></li></ul><p>This direction favours clarity over decoration. The application should feel like a carefully designed financial instrument, not a marketing landing page, trading terminal, bank website, or generic admin dashboard.</p><h3 id="_2-3-primary-user-journey" tabindex="-1">2.3 Primary user journey <a class="header-anchor" href="#_2-3-primary-user-journey" aria-label="Permalink to “2.3 Primary user journey”">​</a></h3><ol><li>Understand what FD Cal does, what data it uses, and what it does not do.</li><li>Configure the investment period and objective.</li><li>Add one or more bank accounts and opening balances.</li><li>Configure inflows, outflows and relevant assumptions.</li><li>Choose a supported strategy and understand any advanced settings.</li><li>Run the simulation and receive clear execution feedback.</li><li>Read a concise result summary and decide whether the result is useful.</li><li>Open or download the full report to inspect bookings, maturities, cash flows, account movements, assumptions and the event ledger.</li><li>Save/export the scenario or report, verify bank terms independently, and share feedback or contribute where appropriate.</li></ol><p>The design should serve both first-time users and experienced users without forcing either group through unnecessary explanation. Advanced detail should be available progressively, not removed.</p><h2 id="_3-design-principles-translated-from-the-charles-skills" tabindex="-1">3. Design principles translated from the Charles Skills <a class="header-anchor" href="#_3-design-principles-translated-from-the-charles-skills" aria-label="Permalink to “3. Design principles translated from the Charles Skills”">​</a></h2><p>The relevant reference skills were re-read from the upstream <a href="https://github.com/LemonFace0309/charles-skills" target="_blank" rel="noreferrer">Charles Skills repository</a>:</p><table tabindex="0"><thead><tr><th>Reference</th><th>Underlying goal</th><th>FD Cal application</th></tr></thead><tbody><tr><td><a href="https://github.com/LemonFace0309/charles-skills/tree/main/skills/charles-unslop" target="_blank" rel="noreferrer">charles-unslop</a></td><td>Remove generic, unnecessary UI; derive design from the actual product; establish hierarchy and a distinctive product moment.</td><td>Preserve FD Cal&#39;s existing identity. Remove duplication and visual noise only where it impedes financial comprehension. Use actual account, rate, schedule and outcome data as the meaningful content.</td></tr><tr><td><a href="https://github.com/LemonFace0309/charles-skills/tree/main/skills/charles-polish" target="_blank" rel="noreferrer">charles-polish</a></td><td>Make all interaction states deliberate; refine hierarchy, focus, touch, responsive behaviour and motion; verify at real sizes.</td><td>Treat configuration, loading, validation, disabled/planned, success, error, results and report states as one coherent workflow. Prioritise reliable interaction over decorative animation.</td></tr><tr><td><a href="https://github.com/LemonFace0309/charles-skills/tree/main/skills/charles-unreasonable-craft" target="_blank" rel="noreferrer">charles-unreasonable-craft</a></td><td>Maintain a coherent system, make deliberate decisions, inspect every relevant viewport/state, and use independent critique.</td><td>Use the repository&#39;s canonical brand tokens; avoid one-off styling. Apply a high quality bar while remaining proportionate to a practical financial tool. Its award-level visual target is not adopted as a product requirement.</td></tr></tbody></table><p>The transferable principles are: product-specific direction, subtraction before addition, coherent design tokens, clear hierarchy, complete state design, accessible interaction, responsive verification, and evidence-based critique.</p><p>The following are <strong>not</strong> adopted literally: award-show visual excess, compulsory three-direction visual explorations for every small correction, generated decorative assets, animation choreography without a user need, or a requirement to make a utilitarian calculator visually unconventional. These would add cost and visual weight without improving FD Cal&#39;s core task.</p><h2 id="_4-non-negotiable-product-and-implementation-constraints" tabindex="-1">4. Non-negotiable product and implementation constraints <a class="header-anchor" href="#_4-non-negotiable-product-and-implementation-constraints" aria-label="Permalink to “4. Non-negotiable product and implementation constraints”">​</a></h2><h3 id="_4-1-preserve-the-existing-brand-system" tabindex="-1">4.1 Preserve the existing brand system <a class="header-anchor" href="#_4-1-preserve-the-existing-brand-system" aria-label="Permalink to “4.1 Preserve the existing brand system”">​</a></h3><p>The canonical colour and typography source is:</p><ul><li><code>src/brand/tokens.css</code></li></ul><p>The browser application consumes it through <code>src/web/styles.css</code>; the VitePress theme imports it through <code>docs/.vitepress/theme/custom.css</code>. These remain the authoritative design-system entry points.</p><p>Current core values include:</p><ul><li>Background: <code>#0b0e13</code></li><li>Raised background: <code>#10151d</code></li><li>Panel: <code>#131923</code></li><li>Raised panel: <code>#192230</code></li><li>Border: <code>#293445</code></li><li>Primary text: <code>#e8edf5</code></li><li>Muted text: <code>#9ba8b8</code></li><li>Accent: <code>#56b4e9</code></li><li>Positive: <code>#55c99a</code></li><li>Danger: <code>#ef7777</code></li><li>Warning: <code>#e9ad58</code></li><li>Strategy: <code>#bd93f9</code></li></ul><p>These are reference values, not an invitation to copy hex values into every new component. Components should consume the CSS custom properties. If a token genuinely needs to change, update the canonical token and assess the web app, docs and report together. Do not introduce a competing palette, random accent colours, unapproved gradients, or isolated hard-coded colours.</p><p>Financial meaning must remain consistent: positive, danger, warning and strategy colours should not be reassigned casually. Colour must never be the only way to distinguish a state or chart series.</p><h3 id="_4-2-the-standalone-report-is-a-hard-boundary" tabindex="-1">4.2 The standalone report is a hard boundary <a class="header-anchor" href="#_4-2-the-standalone-report-is-a-hard-boundary" aria-label="Permalink to “4.2 The standalone report is a hard boundary”">​</a></h3><p>The generated HTML report must remain a portable, standalone document. Once generated, it must not fetch styles, fonts, scripts, images, chart libraries, metadata, bank rates, or any other data from the internet.</p><p>The report must contain everything required to render its own presentation and supplied result data:</p><ul><li>Embedded report CSS.</li><li>Embedded report JavaScript.</li><li>Embedded brand colour values derived from the canonical token source at generation/build time.</li><li>Embedded chart data and all content needed for the report.</li><li>Inline or embedded lightweight assets only where they are justified.</li></ul><p>No runtime CDN, remote stylesheet, remote font, remote image, external script, API request or network-dependent rendering is permitted. The report must still work when opened from a local file with the device offline.</p><p>Do not solve this by copying the entire brand stylesheet into the report. Extract/compile only the small set of tokens the report needs. Keep the report&#39;s embedded design payload compact and avoid adding a UI framework or charting dependency for cosmetic convenience. Native HTML, CSS, SVG/canvas and the existing report code are preferred.</p><p>The report must not depend on the original web application being open, on local storage, or on a server after it has been generated.</p><h3 id="_4-3-preserve-the-summary-report-division" tabindex="-1">4.3 Preserve the summary/report division <a class="header-anchor" href="#_4-3-preserve-the-summary-report-division" aria-label="Permalink to “4.3 Preserve the summary/report division”">​</a></h3><p>This is a deliberate product contract, not an audit defect.</p><p><strong>In-app result summary:</strong> a concise decision-level overview. It should present the key outcome metrics, the relevant scenario context, important warnings/status and clear actions to open/download the report or export the configuration. It must not become a second report.</p><p><strong>Standalone HTML report:</strong> the detailed record. It is the place for individual FD bookings, product and account details, maturity history, cash-flow schedules, portfolio progression, transfers, capital movements, analytics and the full event ledger.</p><p>Do not move booking rows, event history, maturity timelines or the full cash-flow ledger into the in-app summary. The report should be progressively navigable, with detailed tables available when users want to inspect them.</p><p>Both surfaces must derive from the same simulation result and configuration. Headline values must reconcile exactly; do not create a second calculation path in the UI or report.</p><h3 id="_4-4-planned-or-unavailable-choices-are-intentional-product-communication" tabindex="-1">4.4 Planned or unavailable choices are intentional product communication <a class="header-anchor" href="#_4-4-planned-or-unavailable-choices-are-intentional-product-communication" aria-label="Permalink to “4.4 Planned or unavailable choices are intentional product communication”">​</a></h3><p>Some unavailable choices (including the currently unavailable Goal mode) are intentionally visible to show users what is being worked on and to invite suggestions or contributions. The audit&#39;s observation that a choice is not selectable must not be interpreted as an instruction to remove it or make it functional prematurely.</p><p>Preserve this roadmap/coming-soon purpose. Improve the communication so users can understand:</p><ul><li>The capability is planned or in progress, not broken.</li><li>It is not currently selectable and will not silently affect the simulation.</li><li>Where to follow progress, suggest improvements, or contribute, using existing repository issue/discussion/contribution routes where appropriate.</li></ul><p>Do not make a disabled option look like an active control. Do not attach a dead click handler or simulate a selection. If it is genuinely non-interactive, use appropriate disabled/non-interactive semantics and visible explanatory text. If a separate “Suggest an improvement” or “Contribute” action is provided, that action must be a real, clearly labelled link or button with a working destination. Keep the roadmap marker distinct from a functional strategy selection.</p><p>This is a product-discovery and community signal, not merely a disabled-control defect.</p><h3 id="_4-5-protect-financial-meaning-and-user-data" tabindex="-1">4.5 Protect financial meaning and user data <a class="header-anchor" href="#_4-5-protect-financial-meaning-and-user-data" aria-label="Permalink to “4.5 Protect financial meaning and user data”">​</a></h3><ul><li>Do not change calculation logic, financial assumptions, strategy behaviour or event-ledger semantics as part of a visual correction.</li><li>Do not imply that FD Cal verifies bank terms, customer age, eligibility, tax status or transaction completion when it does not.</li><li>Retain clear distinctions between nominal product rates, portfolio returns, money-weighted returns, gross interest, AIT, fees, principal and net interest.</li><li>Keep local scenario data local unless the user explicitly chooses an export/share action.</li><li>Treat downloaded reports as potentially sensitive: they can contain account labels, balances, selected products, bookings and event history. Explain this at the point of export/share without blocking normal use.</li><li>Use synthetic/anonymised fixtures in tests and documentation.</li></ul><h2 id="_5-current-foundations-to-retain" tabindex="-1">5. Current foundations to retain <a class="header-anchor" href="#_5-current-foundations-to-retain" aria-label="Permalink to “5. Current foundations to retain”">​</a></h2><p>The audit and source review establish that FD Cal already has meaningful foundations:</p><ul><li>A shared brand token file used by the web app and documentation theme.</li><li>A four-part scenario configuration model.</li><li>Strategy-dependent configuration and validation.</li><li>Browser-local scenario persistence and configuration import/export.</li><li>A shared JavaScript calculation engine used by the browser and CLI.</li><li>A concise in-app result summary and a separate HTML report generator.</li><li>A report with portfolio, execution, cash-flow and ledger detail.</li><li>Existing responsive and reduced-motion CSS.</li><li>Existing page metadata, Open Graph/Twitter metadata and structured WebApplication metadata in the web entry point.</li><li>Documentation metadata/canonical URL generation in the VitePress configuration.</li><li>Separate web and documentation build/deployment workflows.</li></ul><p>The implementation plan should improve these foundations rather than replace them. In particular, <strong>meta tags are not a current priority</strong>: the basic metadata layer already exists. More detailed metadata review can be part of a final release check. Analytics and tracking are explicitly deferred until a later, separately scoped phase. Do not add analytics scripts, cookies, tracking pixels, telemetry endpoints or third-party analytics dependencies in this work.</p><h2 id="_6-prioritised-implementation-programme" tabindex="-1">6. Prioritised implementation programme <a class="header-anchor" href="#_6-prioritised-implementation-programme" aria-label="Permalink to “6. Prioritised implementation programme”">​</a></h2><p>The phases are ordered to reduce rework. Each phase should be completed and verified before broadening the scope. Keep commits focused and avoid combining visual changes with financial-engine changes.</p><h3 id="phase-0-—-revalidate-and-establish-the-implementation-baseline" tabindex="-1">Phase 0 — Revalidate and establish the implementation baseline <a class="header-anchor" href="#phase-0-—-revalidate-and-establish-the-implementation-baseline" aria-label="Permalink to “Phase 0 — Revalidate and establish the implementation baseline”">​</a></h3><p><strong>Goal:</strong> ensure the plan is applied to the current branch state, not blindly to stale audit observations.</p><p>Work:</p><ol><li>Read the audit and this plan before implementation.</li><li>Re-fetch the current source and compare it with the audit&#39;s reviewed revision.</li><li>Reproduce the relevant current states in a real browser at desktop and mobile widths when a browser runtime is available.</li><li>Record screenshots for the first-use state, populated configuration, validation errors, loading/run state, result summary, generated report and documentation pages. If browser capture is unavailable, record this as pending evidence; do not infer visual success from source inspection.</li><li>Identify which findings are still present, already fixed, or no longer relevant.</li><li>Record the current test baseline and report size baseline.</li></ol><p>Deliverable: a short implementation baseline note with source SHA, screenshots, confirmed findings and any changed assumptions.</p><p>Exit criteria:</p><ul><li>No fix is based solely on a stale source observation.</li><li>Each selected change maps to a user problem and an audit finding or a clearly documented improvement opportunity.</li><li>Existing functionality and the calculation/report contracts are understood before edits begin.</li></ul><h3 id="phase-1-—-first-use-comprehension-and-scenario-workflow" tabindex="-1">Phase 1 — First-use comprehension and scenario workflow <a class="header-anchor" href="#phase-1-—-first-use-comprehension-and-scenario-workflow" aria-label="Permalink to “Phase 1 — First-use comprehension and scenario workflow”">​</a></h3><p><strong>Priority:</strong> High<br><strong>Goal:</strong> make the main journey understandable without turning the app into a tutorial.</p><p>Work:</p><ol><li>Refine the opening explanation to say what the user can do, that the calculation runs in the browser, and that scenario data remains in the browser.</li><li>Clarify the four configuration stages and their order. Keep labels and navigation consistent across the rail, section headings and status feedback.</li><li>Make account, inflow and outflow concepts understandable in the context of the user&#39;s financial task. Use concise contextual help only where a term or decision is not self-explanatory.</li><li>Review consolidation-account terminology and explain its role at the point of selection.</li><li>Improve scheduled-date entry and validation so date syntax and accepted ranges are obvious. Do not change the underlying schedule model merely to change the control.</li><li>Review dense cash-flow configuration. Group related controls and make conditional fields predictable. Preserve advanced options; progressively reveal them when appropriate.</li><li>Clarify senior/minor product inclusion. State that these switches include age-segmented products in the candidate set and do not verify a person&#39;s age or eligibility. Where available, expose the relevant product conditions in the detailed information/report rather than implying automatic verification.</li><li>Keep strategy-specific settings grouped under their strategy and explain their effect in plain, precise language. Separate financial assumptions from optimisation/search-budget controls.</li><li>Make the unavailable Goal mode communicate “in progress” and its contribution path without making the selection itself clickable or implying it can run.</li><li>Review import/export and local-persistence messaging so users understand what is stored and what leaves the browser.</li></ol><p>Acceptance criteria:</p><ul><li>A first-time user can identify the required inputs and run a supported scenario without needing to infer hidden syntax.</li><li>Invalid fields identify the problem and the expected format without losing unrelated inputs.</li><li>Advanced controls remain available and do not overwhelm the primary path.</li><li>Unavailable functionality is clearly marked as planned/in progress and cannot be mistaken for an active mode.</li><li>No change to the underlying financial configuration schema or simulation result is introduced without separate approval and regression tests.</li></ul><h3 id="phase-2a-—-non-blocking-background-computation-and-run-lifecycle" tabindex="-1">Phase 2A — Non-blocking background computation and run lifecycle <a class="header-anchor" href="#phase-2a-—-non-blocking-background-computation-and-run-lifecycle" aria-label="Permalink to “Phase 2A — Non-blocking background computation and run lifecycle”">​</a></h3><p><strong>Priority:</strong> Critical<br><strong>Goal:</strong> expensive optimisation and simulation work must not block the browser&#39;s main thread. The page must remain responsive, continue painting, and communicate honestly that a computation is in progress.</p><p>This is a functional performance requirement, not a spinner/visual polish task. The current browser submit flow awaits preparation and then calls the synchronous <code>simulate(c)</code> path on the main thread. Awaiting a Promise around synchronous CPU work does not move that work off the main thread; the simulation itself must execute in a Web Worker (or another genuine background execution context).</p><h4 id="architecture" tabindex="-1">Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to “Architecture”">​</a></h4><ol><li>Introduce a dedicated browser worker entry point for the CPU-intensive simulation path. Keep the existing shared calculation engine and strategy implementations as the source of financial behaviour; do not fork or reimplement the algorithms for the worker.</li><li>The current web app is a static native-ES-module application: <code>package.json</code> has no bundler/build dependency and <code>src/web/README.md</code> documents direct static serving. Do not introduce a bundler for this work. Load the worker with the browser-native module-worker form <code>new Worker(new URL(&quot;./simulation.worker.js&quot;, import.meta.url), { type: &quot;module&quot; })</code>; keep the worker and its task module beside the app entry point, and verify the isolated web artifact preserves their relative paths/imports.</li><li>Keep DOM access, form state, status text, elapsed-time display, report Blob creation/download and result rendering on the main thread. The worker receives a serializable, validated computation payload and returns a serializable result payload.</li><li>Complete required bank-rate/catalogue loading and configuration validation before dispatching work. Show a preparation/loading state during this stage; distinguish it from the actual CPU computation phase.</li><li>Wrap worker execution in a Promise-based runner on the main thread. The Promise must settle exactly once on success, worker-reported error, message deserialisation failure, worker startup failure, timeout if a defensible timeout is adopted, or explicit cancellation/supersession. Always release worker resources and event handlers.</li><li>Use structured-clone-safe inputs and outputs. Do not send DOM objects, functions, class instances with required prototype behaviour, or mutable application state. Convert FD options and configuration to the plain serializable representation required by the engine, then reconstruct required domain objects inside the worker where appropriate.</li><li>Preserve deterministic parity with the existing CLI/shared engine. Worker execution must call the same <code>SimulationEngine</code> and strategy classes with equivalent inputs. Do not change strategy defaults, tie-breakers, numerical precision or financial rules as part of this refactor.</li><li>Do not silently fall back to running a heavy simulation synchronously on the main thread if Worker creation fails. Present a recoverable, actionable error. A synchronous fallback would reintroduce the browser-freeze defect this phase is intended to remove.</li><li>Avoid unnecessary copying of large catalogue payloads. Measure structured-clone cost; use transferable buffers only where the data format and ownership semantics make this safe. Do not detach buffers or mutate cached catalogue data still needed by the app.</li></ol><h4 id="run-identity-deduplication-and-supersession" tabindex="-1">Run identity, deduplication and supersession <a class="header-anchor" href="#run-identity-deduplication-and-supersession" aria-label="Permalink to “Run identity, deduplication and supersession”">​</a></h4><p>The runner must have explicit request identity and single-flight semantics.</p><ul><li>Compute a stable request fingerprint from the effective validated scenario, selected strategy settings, relevant financial assumptions and the exact catalogue/data snapshot used. Avoid relying only on raw form JSON if equivalent configurations can serialize differently or catalogue data can change.</li><li>If a request with the same fingerprint is already running, do not start another worker or duplicate the computation. Reuse/return the in-flight Promise and preserve the existing visible run state. Repeated clicks/submissions must not create duplicate work.</li><li>Keep the existing completed-result optimisation: if the effective fingerprint is unchanged and the matching result is still valid for the current catalogue snapshot, reuse the completed result rather than recomputing. Make this behaviour clear and do not hide a failed or stale run behind a false cache hit.</li><li>If the user changes the scenario while a run is in progress and submits the new configuration, treat it as a new request. Use a latest-request-wins policy: cancel/terminate the obsolete worker, invalidate its request identity, and start the new request after its inputs are ready. Do not allow two expensive optimisation jobs to compete for CPU by default.</li><li>Ignore any late message/result from a superseded worker. Only the currently active request fingerprint may update the result summary, report, cache key or error state.</li><li>If the user edits the form but does not submit again, the old run may finish, but its result must remain clearly associated with the exact configuration that produced it. Do not imply that it represents unsaved edits. Prefer marking the result as belonging to the last submitted scenario and indicate when the current form differs.</li><li>Disable only actions that would cause unsafe duplicate execution. Do not freeze the whole form unnecessarily; users should be able to inspect or edit inputs while a computation runs. The run action should clearly communicate whether it will reuse the in-flight request, start a changed scenario, or is temporarily unavailable.</li></ul><h4 id="progress-and-elapsed-time-feedback" tabindex="-1">Progress and elapsed-time feedback <a class="header-anchor" href="#progress-and-elapsed-time-feedback" aria-label="Permalink to “Progress and elapsed-time feedback”">​</a></h4><ul><li>Keep a persistent, polite live status region visible throughout preparation and computation. Use text such as “Loading bank data…”, “Preparing scenario…”, and “Computing Absolute R+…” rather than presenting every phase as generic loading.</li><li>Once the worker actually starts, start a monotonic elapsed-time clock (for example, based on <code>performance.now()</code>). Display elapsed time in a human-readable format such as <code>00:04</code> or <code>1m 12s</code>; update it on the main thread so the page remains responsive.</li><li>Stop and freeze the compute elapsed timer on success, error or cancellation. Do not include bank-data loading time in the compute-only figure. If total end-to-end duration is useful, label it separately from worker compute duration.</li><li>On success, show completion and elapsed duration briefly or alongside the result metadata without obscuring the result summary. On failure, retain the useful phase and elapsed context in the error state. On cancellation/supersession, do not announce a successful completion.</li><li>Do not display a fabricated percentage. Only show determinate progress if the engine exposes meaningful, measured progress events. If it does not, use an indeterminate progress indicator plus elapsed time.</li><li>Continue to honour reduced-motion preferences. The status text and elapsed duration must remain useful with animation disabled and must not rely on colour alone.</li><li>Avoid announcing every timer tick through an assertive screen-reader alert. Keep the status region polite and use a sensible announcement cadence; the visual timer can update more frequently than assistive-technology announcements.</li></ul><h4 id="failure-cancellation-and-lifecycle-handling" tabindex="-1">Failure, cancellation and lifecycle handling <a class="header-anchor" href="#failure-cancellation-and-lifecycle-handling" aria-label="Permalink to “Failure, cancellation and lifecycle handling”">​</a></h4><ul><li>Handle worker construction failure, import/runtime errors, thrown strategy errors, invalid result payloads and unexpected worker termination.</li><li>On navigation/unload, supersession or explicit cancellation, terminate the worker and clean up the timer and listeners.</li><li>Ensure a worker error cannot leave the run button disabled, the spinner active, a stale “computing” message visible or a Promise permanently pending.</li><li>Ensure a worker result is validated before it is passed to report generation. Report generation remains on the main thread unless separately measured and proven to be a material source of blocking.</li><li>Keep diagnostic detail for developers while showing a clear user-facing recovery message. Never include private scenario data in telemetry; analytics/telemetry remains deferred.</li></ul><h4 id="acceptance-criteria" tabindex="-1">Acceptance criteria <a class="header-anchor" href="#acceptance-criteria" aria-label="Permalink to “Acceptance criteria”">​</a></h4><ul><li>The expensive simulation executes in a Web Worker, not on the browser main thread.</li><li>While a deliberately slow test scenario is running, the page continues to paint, scroll, accept safe input edits and respond to browser interactions; the browser does not report the page as unresponsive.</li><li>The visible status distinguishes preparation from actual computation and names the selected strategy.</li><li>A live elapsed timer starts when worker computation starts and stops accurately on completion, error or cancellation.</li><li>Repeated submission of the same in-flight fingerprint starts exactly one computation.</li><li>Submitting a changed scenario supersedes the old computation; an old worker result cannot overwrite the newer scenario.</li><li>Re-running an unchanged, already completed scenario reuses the valid result according to the existing cache policy and does not misleadingly display a new computation.</li><li>Worker and main-thread results match for representative fixtures, including all browser-supported strategies, cash-flow types, fees, AIT settings and edge cases.</li><li>Worker failure and unsupported environments fail visibly and recoverably; there is no silent synchronous fallback.</li><li>Existing CLI results and benchmark behaviour remain unchanged.</li><li>Worker resources, timers and event listeners are cleaned up after every terminal path.</li></ul><h4 id="required-tests" tabindex="-1">Required tests <a class="header-anchor" href="#required-tests" aria-label="Permalink to “Required tests”">​</a></h4><ol><li>Unit tests for request fingerprint stability and catalogue-snapshot inclusion.</li><li>Runner tests for success, error, message error, startup failure, cancellation, supersession and cleanup.</li><li>Single-flight test: multiple submissions with one fingerprint dispatch one worker computation.</li><li>Supersession test: request B replaces request A; a late response from A is ignored.</li><li>Completed-result reuse test: unchanged input and unchanged catalogue reuse the prior result; changed catalogue invalidates it.</li><li>Parity tests comparing worker and direct shared-engine outputs for deterministic fixtures.</li><li>Browser end-to-end test with an intentionally expensive fixture: verify elapsed time advances and a main-thread heartbeat/UI interaction continues during computation.</li><li>Accessibility test for phase announcements, timer labelling and reduced-motion behaviour.</li><li>Production-build test confirming the worker is emitted and loads from the deployed web artifact.</li><li>Regression test confirming CLI execution remains independent of browser worker infrastructure.</li></ol><h3 id="phase-2-—-interaction-quality-and-execution-feedback" tabindex="-1">Phase 2 — Interaction quality and execution feedback <a class="header-anchor" href="#phase-2-—-interaction-quality-and-execution-feedback" aria-label="Permalink to “Phase 2 — Interaction quality and execution feedback”">​</a></h3><p><strong>Priority:</strong> High<br><strong>Goal:</strong> make every interaction state predictable and trustworthy.</p><p>Work:</p><ol><li>Map the full states of each major control and workflow: initial/loading, ready, focused, invalid, disabled, running, success, failure and recovery.</li><li>Ensure the catalogue loading state is clear and that controls cannot be used in a misleading partially initialised state.</li><li>Review synchronous simulation feedback. The UI should clearly indicate that a run has started and avoid suggesting that the page is still interactive if the main thread is occupied. Any architectural change such as workers or asynchronous execution is a separate performance task and must preserve engine parity.</li><li>Prevent accidental duplicate submissions while a run is active; restore the correct state on failure.</li><li>Provide actionable error messages. Avoid exposing stack traces or raw internal errors to ordinary users; retain diagnostics in developer-facing channels without logging private scenario data.</li><li>Audit keyboard focus order, visible focus, labels, help affordances, disabled semantics, touch targets and status announcements.</li><li>Use motion only when it communicates a state change. Keep transitions short, interruptible and consistent with the existing motion token. Honour reduced-motion preferences.</li><li>Avoid adding extra badges, icons, helper lines, containers or animation unless each communicates unique information.</li></ol><p>Acceptance criteria:</p><ul><li>Keyboard users can complete the primary workflow and understand validation/run states.</li><li>Focus is visible and follows a logical sequence.</li><li>Running, success and failure are distinguishable without relying on colour alone.</li><li>No control appears actionable when it is not.</li><li>Reduced-motion users receive the same information and functional outcome.</li><li>No duplicate run or stale UI state is produced during normal interaction.</li></ul><h3 id="phase-3-—-results-summary-and-standalone-report" tabindex="-1">Phase 3 — Results summary and standalone report <a class="header-anchor" href="#phase-3-—-results-summary-and-standalone-report" aria-label="Permalink to “Phase 3 — Results summary and standalone report”">​</a></h3><p><strong>Priority:</strong> Critical<br><strong>Goal:</strong> establish a coherent two-level result experience while keeping the report portable and lightweight.</p><h4 id="_3a-in-app-result-summary" tabindex="-1">3A. In-app result summary <a class="header-anchor" href="#_3a-in-app-result-summary" aria-label="Permalink to “3A. In-app result summary”">​</a></h4><p>Work:</p><ol><li>Preserve the concise six-metric summary for scoped results: gross interest, AIT withheld, transfer fees, net interest, final value and capital invested, with goal-specific metrics only when the relevant goal outcome exists.</li><li>Include only the minimum scenario context needed to interpret the metrics (period, strategy and meaningful status/warnings).</li><li>Keep report open/download and configuration export actions clear and distinct.</li><li>Do not insert booking lists, maturity history, detailed cash flows, transfer histories, account ledgers or full event chronology into the summary.</li><li>Ensure all displayed values are taken from the same result object and reconcile with the report.</li></ol><p>Acceptance criteria:</p><ul><li>A user can understand the headline outcome quickly.</li><li>The summary remains materially shorter and simpler than the report.</li><li>No detailed booking or event history is duplicated in the summary.</li></ul><h4 id="_3b-standalone-report-structure-and-comprehension" tabindex="-1">3B. Standalone report structure and comprehension <a class="header-anchor" href="#_3b-standalone-report-structure-and-comprehension" aria-label="Permalink to “3B. Standalone report structure and comprehension”">​</a></h4><p>Work:</p><ol><li>Keep the report as the full inspection surface: overview, portfolio outcome, execution plan, performance analysis, investment portfolio, scheduled cash flows, capital movements and full event ledger.</li><li>Improve section hierarchy and orientation so users can move from overview to evidence without losing context.</li><li>Make report language explicit about simulation versus execution. Execution instructions are a planning checklist, not bank instructions, transfer commands or transaction confirmations.</li><li>Distinguish product nominal rates from portfolio-level annualised/money-weighted return. Explain the assumptions and cash-flow timing behind return measures.</li><li>Preserve traceability of each booking: bank/product, account, principal, rate, term, booking date, maturity date, payout type and relevant interest/tax treatment.</li><li>Make cash flows, transfers, fees, maturities, AIT and event-ledger movements reconcile. Keep outstanding/unpaid outflows visibly distinct from paid obligations.</li><li>Improve provenance so a saved report can identify the simulation period, strategy and the catalogue/data snapshot used. Add a generated timestamp and stable data/catalogue fingerprint only if these values are available reliably from the build/result context. Do not invent provenance or claim rates were verified live.</li><li>Make the report&#39;s privacy implications clear before download/share: the file can contain scenario account labels, balances, bookings and event history.</li><li>Keep large detail tables collapsible where this genuinely reduces initial visual load, but ensure keyboard users can open them and the collapsed state does not hide critical warnings or summary information.</li></ol><p>Acceptance criteria:</p><ul><li>A user can trace important portfolio totals into the underlying bookings and event history.</li><li>Report labels distinguish estimates, simulated events, assumptions and manual steps.</li><li>Summary and report financial values reconcile exactly.</li><li>The report remains useful as a saved historical record, with honest provenance.</li><li>The report does not imply bank confirmation or guaranteed product eligibility.</li></ul><h4 id="_3c-report-visual-system-and-offline-packaging" tabindex="-1">3C. Report visual system and offline packaging <a class="header-anchor" href="#_3c-report-visual-system-and-offline-packaging" aria-label="Permalink to “3C. Report visual system and offline packaging”">​</a></h4><p>Work:</p><ol><li>Treat <code>src/brand/tokens.css</code> as the single source of truth for brand colours and typography.</li><li>Provide a small, explicit report-token export/embedding path. At generation/build time, resolve the relevant canonical tokens into the report&#39;s inline CSS; do not load <code>tokens.css</code> from a relative path at report-open time.</li><li>Keep report-specific layout variables local to the report only where they are not brand tokens (for example, table spacing or chart dimensions). Brand colours, typography and shared radii must not drift.</li><li>Review report chart series colours against the brand palette and contrast requirements. Series may use a restrained, deterministic data palette where necessary to distinguish many accounts; it must remain legible, repeatable and clearly separate from semantic status colours. Do not replace useful series differentiation with a single accent.</li><li>Preserve native lightweight chart rendering. Do not add a chart framework unless a documented accessibility or correctness requirement cannot reasonably be met with the current implementation.</li><li>Ensure all CSS, JavaScript, chart data and required assets are embedded in the output. Avoid remote fonts and assets; use the existing system font stack/fallbacks.</li><li>Add a report self-containment check that scans generated HTML for remote resource references and verifies that the report opens with network access disabled.</li><li>Track generated report size against a recorded baseline. Avoid shipping unused CSS/JS, duplicate token payloads or unnecessary libraries. Set a size budget after measuring representative small, normal and large reports rather than choosing an arbitrary limit before measuring.</li></ol><p>Acceptance criteria:</p><ul><li>Generated HTML has no required external network dependencies.</li><li>The report opens and its controls/charts work from a local file while offline.</li><li>Embedded brand tokens match the canonical source at the time of generation.</li><li>Report file size grows primarily with scenario data, not duplicated libraries or unused styling.</li><li>No separate, drifting report palette is introduced.</li></ul><h4 id="_3d-report-accessibility-responsive-and-print-behaviour" tabindex="-1">3D. Report accessibility, responsive and print behaviour <a class="header-anchor" href="#_3d-report-accessibility-responsive-and-print-behaviour" aria-label="Permalink to “3D. Report accessibility, responsive and print behaviour”">​</a></h4><p>Work:</p><ol><li>Provide a non-hover-only way to inspect chart values. Where a canvas remains, provide an adjacent accessible data representation or equivalent keyboard-operable controls.</li><li>Ensure chart descriptions communicate what is plotted, units, dates and series. Do not rely on colour alone.</li><li>Verify collapsible sections, table navigation, focus order and accessible names.</li><li>Test wide tables at narrow viewports. Preserve useful row/column context and avoid clipping critical values.</li><li>Review print CSS so navigation and interactive-only controls do not waste printed pages, while key sections, tables and chart information remain readable.</li><li>Respect reduced motion and avoid unnecessary animation in a report that is primarily read and inspected.</li></ol><p>Acceptance criteria:</p><ul><li>Important chart information is available without pointer hover.</li><li>Report navigation and disclosure controls work with keyboard.</li><li>Report is readable at phone, tablet, laptop and wide desktop widths.</li><li>Print/PDF output preserves critical content and does not clip columns or warnings.</li><li>Offline, keyboard and reduced-motion behaviour are covered by repeatable tests.</li></ul><h3 id="phase-4-—-documentation-as-part-of-the-product" tabindex="-1">Phase 4 — Documentation as part of the product <a class="header-anchor" href="#phase-4-—-documentation-as-part-of-the-product" aria-label="Permalink to “Phase 4 — Documentation as part of the product”">​</a></h3><p><strong>Priority:</strong> High<br><strong>Goal:</strong> make the documentation the reliable companion to the actual app, not a separate developer-only appendix.</p><p>Work:</p><ol><li>Organise the user-facing path around what a person is trying to do: understand FD Cal, prepare a scenario, configure accounts/cash flows, choose a strategy, interpret results, inspect/download the report and understand limitations.</li><li>Keep architecture, engine internals, benchmarks and strategy implementation detail available, but place them in clearly identified technical/reference sections.</li><li>Ensure screenshots and examples reflect the current application. Use synthetic data only; never publish personal financial information.</li><li>Document the distinction between the in-app summary and the full HTML report, including offline use and report privacy.</li><li>Explain that age-segmented product inclusion does not prove customer eligibility; explain the meaning of the consolidation account and the major financial assumptions.</li><li>Document the planned Goal capability accurately and provide the same contribution/feedback path as the app.</li><li>Ensure docs navigation, cross-links, edit links and app links work. Avoid duplicated guidance that can drift.</li><li>Maintain separate documentation build/deployment behaviour. A docs change should not unnecessarily block or trigger the web app deployment; the existing component-specific publishing model should remain intact.</li><li>Add a concise “verify with the bank” and “not financial/tax advice” statement where it helps users interpret outputs, without repeating it on every page.</li></ol><p>Acceptance criteria:</p><ul><li>A new user can follow the documentation in the same order as the app workflow.</li><li>Every documented control/strategy matches the current supported implementation.</li><li>The report and app are described consistently.</li><li>Technical documentation remains available without dominating the user guide.</li><li>Documentation builds and deploys independently according to the existing workflow.</li></ul><h3 id="phase-5-—-cross-surface-consistency-and-final-verification" tabindex="-1">Phase 5 — Cross-surface consistency and final verification <a class="header-anchor" href="#phase-5-—-cross-surface-consistency-and-final-verification" aria-label="Permalink to “Phase 5 — Cross-surface consistency and final verification”">​</a></h3><p><strong>Priority:</strong> High<br><strong>Goal:</strong> ensure the app, report and documentation feel like one product and that fixes are demonstrated rather than assumed.</p><p>Work:</p><ol><li>Compare app, report and docs against the canonical tokens for colour, type, focus, border, radius and spacing.</li><li>Verify desktop, mobile and awkward intermediate widths. Minimum viewport set: 360, 390, 768, 1024, 1280, 1440 and 1920 px.</li><li>Run keyboard-only checks on the full scenario journey and the report.</li><li>Test reduced motion, light/dark system preference where supported, and print output.</li><li>Test representative scenarios: simple single account; multi-account; recurring and one-off inflows; strict and best-effort outflows; same-bank/inter-bank transfers and fees; cumulative/periodic-interest/installment products; AIT on/off; senior/minor product inclusion; and large event ledgers.</li><li>Reconcile summary, report and raw result values for gross interest, AIT, fees, net interest, capital and final value.</li><li>Verify report offline operation by disabling network after generation.</li><li>Run the full Node.js suite, syntax checks, web build, docs build and relevant component deployment workflows.</li><li>Inspect browser console/network logs and verify there are no broken assets, external report requests, layout shifts or uncaught errors. Confirm the simulation runs in a worker, the main thread remains responsive, elapsed timing is accurate, and duplicate/superseded requests behave as specified.</li><li>Capture before/after screenshots and record the tested source SHA and deployed component artifact SHAs.</li></ol><p>Acceptance criteria:</p><ul><li>All selected audit findings are either fixed, explicitly deferred with rationale, or shown to be no longer applicable.</li><li>All relevant existing tests pass and new regression/end-to-end tests cover changed behaviour.</li><li>No financial-engine regression is introduced.</li><li>Browser-level evidence exists for the visual and interaction claims.</li><li>The report passes offline and data-reconciliation checks.</li><li>Web and docs artifacts correspond to the intended source revision.</li></ul><h2 id="_7-explicitly-deferred-work" tabindex="-1">7. Explicitly deferred work <a class="header-anchor" href="#_7-explicitly-deferred-work" aria-label="Permalink to “7. Explicitly deferred work”">​</a></h2><p>The following are intentionally outside the current implementation programme unless separately approved:</p><ul><li><strong>Analytics/telemetry:</strong> deferred. No analytics provider, tracking script, cookies, telemetry endpoint or user-behaviour instrumentation in this work.</li><li><strong>Expanded SEO/metadata campaign:</strong> basic metadata already exists in the app and docs. Only correct obvious metadata defects during final QA; a broader SEO strategy is a separate task.</li><li><strong>Decorative redesign or new brand palette:</strong> not required. Retain the existing FD Cal tokens.</li><li><strong>New animation system:</strong> not required. Use motion only to communicate meaningful state changes.</li><li><strong>New charting framework or UI framework:</strong> not required. Prefer existing native report implementation.</li><li><strong>Financial-engine/strategy changes:</strong> separate scope with domain review, benchmark/regression evidence and explicit approval.</li><li><strong>New backend or user accounts:</strong> not implied by this plan. Preserve the browser-local operating model.</li><li><strong>Automatic verification of bank rates, depositor age or eligibility:</strong> do not imply such capabilities.</li></ul><h2 id="_8-implementation-order-and-change-management" tabindex="-1">8. Implementation order and change management <a class="header-anchor" href="#_8-implementation-order-and-change-management" aria-label="Permalink to “8. Implementation order and change management”">​</a></h2><p>Recommended delivery order:</p><ol><li>Phase 0 baseline and finding triage.</li><li>Phase 1 first-use and configuration comprehension.</li><li>Phase 2A worker-based computation and run lifecycle (critical dependency for trustworthy execution feedback).</li><li>Phase 2 interaction and execution feedback.</li><li>Phase 3A summary contract and 3B report content/traceability.</li><li>Phase 3C standalone token packaging and 3D report accessibility/responsive/print.</li><li>Phase 4 user documentation.</li><li>Phase 5 cross-surface verification.</li></ol><p>Keep each PR focused. Prefer one coherent workflow or report concern per PR rather than a large “UI cleanup” change. Do not mix calculation-engine refactors into UI commits. If a visual correction exposes a financial-model ambiguity, document it and open a separate issue instead of silently changing the model.</p><p>For each implementation PR:</p><ul><li>Link the relevant audit finding(s) and this plan section.</li><li>State the user problem and the intended outcome.</li><li>List the surfaces affected (web app, report, docs).</li><li>Include before/after screenshots for visual changes.</li><li>Add or update automated tests for behaviour changes.</li><li>Record accessibility and responsive checks.</li><li>Confirm the standalone report has no external dependencies if report code changed.</li><li>Confirm summary/report values reconcile if result presentation changed.</li><li>State what is deliberately unchanged.</li></ul><h2 id="_9-verification-matrix" tabindex="-1">9. Verification matrix <a class="header-anchor" href="#_9-verification-matrix" aria-label="Permalink to “9. Verification matrix”">​</a></h2><p>The audit&#39;s RPT-01–RPT-18 matrix remains the detailed report test baseline. The following additional product-level cases should be included in the implementation acceptance process.</p><table tabindex="0"><thead><tr><th>ID</th><th>Surface</th><th>Test</th><th>Pass condition</th></tr></thead><tbody><tr><td>UX-01</td><td>App first use</td><td>Open with no prior saved scenario</td><td>Purpose, local data behaviour and first configuration step are clear.</td></tr><tr><td>UX-02</td><td>Configuration</td><td>Configure one account and one cash flow</td><td>User can complete the primary path without hidden syntax or unexplained terminology.</td></tr><tr><td>UX-03</td><td>Configuration</td><td>Submit invalid dates and amounts</td><td>Field-specific correction is clear; unrelated data is retained.</td></tr><tr><td>UX-04</td><td>Planned feature</td><td>Inspect unavailable Goal mode</td><td>Clearly marked in progress; not selectable; real feedback/contribution route available separately.</td></tr><tr><td>UX-05</td><td>Strategy</td><td>Switch supported strategies</td><td>Only relevant settings appear; descriptions match actual behaviour.</td></tr><tr><td>UX-06</td><td>Eligibility</td><td>Include age-segmented products</td><td>No implication that depositor eligibility has been verified.</td></tr><tr><td>UX-07</td><td>Execution</td><td>Run a normal and a deliberately expensive scenario</td><td>Simulation runs in a worker; UI remains responsive; phase status and elapsed compute time are accurate.</td></tr><tr><td>UX-07a</td><td>Execution</td><td>Submit the same scenario repeatedly while active</td><td>One in-flight worker computation only; no duplicate CPU work.</td></tr><tr><td>UX-07b</td><td>Execution</td><td>Change configuration and submit while a run is active</td><td>Old run is cancelled/superseded; stale output cannot replace the latest request.</td></tr><tr><td>UX-07c</td><td>Execution</td><td>Re-run an unchanged completed scenario</td><td>Valid completed result is reused without pretending a new computation started.</td></tr><tr><td>UX-08</td><td>Results</td><td>Inspect in-app summary</td><td>Only decision-level summary; no booking/history ledger.</td></tr><tr><td>UX-09</td><td>Results/report</td><td>Compare summary with report</td><td>Headline metrics reconcile exactly.</td></tr><tr><td>UX-10</td><td>Report</td><td>Generate and reopen saved report offline</td><td>All report sections, charts and controls work without network.</td></tr><tr><td>UX-11</td><td>Report</td><td>Inspect report at 360–1920 px</td><td>No clipped critical content; navigation and tables remain usable.</td></tr><tr><td>UX-12</td><td>Accessibility</td><td>Keyboard-only app and report walkthrough</td><td>Focus visible; all important actions and chart data accessible.</td></tr><tr><td>UX-13</td><td>Documentation</td><td>Follow user guide against current app</td><td>Labels, routes, capabilities and limitations match the app.</td></tr><tr><td>UX-14</td><td>Publishing</td><td>Build web and docs components</td><td>Independent deployment paths remain functional and source revisions are recorded.</td></tr></tbody></table><h2 id="_10-definition-of-done" tabindex="-1">10. Definition of done <a class="header-anchor" href="#_10-definition-of-done" aria-label="Permalink to “10. Definition of done”">​</a></h2><p>The programme is complete when:</p><ul><li>The primary scenario workflow is understandable and usable for first-time and experienced users.</li><li>Expensive browser computation runs in a background worker through a Promise-based lifecycle; the UI stays responsive and reports truthful phase/elapsed-time feedback.</li><li>Identical in-flight requests are single-flight deduplicated; changed requests supersede stale work without allowing stale results to render.</li><li>Existing brand tokens remain the single source of truth across the app and docs; the report embeds the relevant token values in its own output.</li><li>The in-app summary remains concise and the standalone report remains the detailed, offline-capable record.</li><li>Planned/unavailable functionality communicates roadmap intent without pretending to be interactive.</li><li>Report content, charts, tables, privacy messaging and provenance are understandable and accessible.</li><li>Documentation follows the user journey and matches the deployed application.</li><li>Analytics remains absent until a separately approved future phase.</li><li>Relevant automated tests, browser checks, responsive checks, keyboard checks, offline checks and financial reconciliation tests pass.</li><li>No unapproved financial calculation, strategy, data-source or privacy behaviour has changed.</li></ul><h2 id="_11-source-references" tabindex="-1">11. Source references <a class="header-anchor" href="#_11-source-references" aria-label="Permalink to “11. Source references”">​</a></h2><ul><li><p><a href="./UI-UX-AUDIT-CHARLES-SKILLS.html">Audit findings and report test matrix</a></p></li><li><p>Canonical brand tokens: <code>src/brand/tokens.css</code></p></li><li><p>Web application markup: <code>src/web/index.html</code></p></li><li><p>Web application behaviour: <code>src/web/app.js</code></p></li><li><p>Simulation engine: <code>src/core/simulation.js</code></p></li><li><p>Strategy implementations: <code>src/strategies/</code></p></li><li><p>Web application styles: <code>src/web/styles.css</code></p></li><li><p>Report generator: <code>src/reporting/html.js</code></p></li><li><p>Standalone report template: <code>src/reporting/template.js</code></p></li><li><p>Documentation VitePress configuration: <code>docs/.vitepress/config.mts</code></p></li><li><p>Documentation theme: <code>docs/.vitepress/theme/custom.css</code></p></li><li><p><a href="./../guide/getting-started.html">Getting started guide</a></p></li><li><p>Contributor guide: <code>CONTRIBUTING.md</code></p></li><li><p><strong>2026-11-08 — History cleanup:</strong> consolidated the implementation file changes into one commit after the original planning/audit commits, preserving a short linear history. The branch retains the original audit/plan history and has a consolidated implementation commit.</p></li></ul>`,144)]])}var s=t(a,[[`render`,o]]);export{i as __pageData,s as default};